import 'dart:convert';
import 'dart:io';
void main(){const p='/private/tmp/dart3d-u3-outline-view-probe-20261028/r1/parent';final lines=File('$p/native-all.log').readAsLinesSync();final pids=lines.where((l)=>l.contains('U3OV create producer')).map((l)=>RegExp(r'Runner\[(\d+):').firstMatch(l)!.group(1)!).toSet();if(pids.length!=1)throw StateError('Probe PID count');final pid=pids.single;final rows=lines.where((l)=>l.contains('Runner[$pid:')).toList();final events=rows.where((l)=>l.contains('com.jasonholtdigital.dart3d:scene')&&!l.contains('U3OV RAW row')).toList();final errors=rows.where((l)=>RegExp(r'fatal|shader.*error|Cannot modify|cross.scene mutation|SCNTransaction|unrecognized selector|UI API called|U3OV GPU-ERROR|U3OV BLOCKED',caseSensitive:false).hasMatch(l)).toList();File('$p/split/native-events.log').writeAsStringSync(events.join('\n')+'\n');File('$p/split/error-query.log').writeAsStringSync(errors.join('\n'));final schedule=events.where((l)=>l.contains('U3OV due ')||l.contains('U3OV public-highlights')||l.contains('U3OV control ')||l.contains('U3OV target-mask-encode')||l.contains('U3OV target-normal-encode')).toList();File('$p/split/schedule.log').writeAsStringSync(schedule.join('\n')+'\n');File('$p/native-summary.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert({'pid':pid,'nativeRows':rows.length,'eventRowsExcludingRawRows':events.length,'errorQueryMatches':errors.length,'dueCount':events.where((l)=>l.contains('U3OV due ')).length,'setClearCount':events.where((l)=>l.contains('U3OV public-highlights')).length,'loggerExit':0,'fullLogRetained':'native-all.log'}));print('Probe PID$pid, ${rows.length} rows, ${errors.length} error-query matches, ${schedule.length} schedule/control events');}
